from multiprocessing import Pool
def make_items(seed):
    rng = np.random.default_rng(seed)
    return np.clip(np.round(rng.weibull(3.0, 5000) * 45), 1, 100).astype(int)
ITEMS = {}
def sim(params, seed):
    items = ITEMS.get(seed)
    if items is None: items = ITEMS[seed] = make_items(seed).tolist()
    newpen = params.get("newpen", 0.0); sw = params.get("switch", 4900)
    a = params.get("a", 0.0); g0 = params.get("g0", 1); b = params.get("b", 0.0)
    w = [1.0 + (a * (g0 - g) / g0 if g < g0 else 0.0) for g in range(101)]
    lin = [ (b * (g0 - g) if g < g0 else 0.0) for g in range(101)]
    w[0] = 0.0; lin[0] = 0.0
    N = [0] * 101; bins = 0
    for t, s in enumerate(items):
        if t >= sw:
            # best fit
            ch = 100
            for c in range(s, 100):
                if N[c]: ch = c; break
        else:
            r = 100 - s
            best = w[r] * (2 * N[r] + 1) + lin[r] + newpen; ch = 100
            for c in range(s, 100):
                if N[c]:
                    r = c - s
                    d = w[r] * (2 * N[r] + 1) + lin[r] - w[c] * (2 * N[c] - 1) - lin[c]
                    if d < best or (d == best and c < ch): best = d; ch = c
        if ch == 100: bins += 1
        else: N[ch] -= 1
        r = ch - s
        if r > 0: N[r] += 1
    lb = math.ceil(sum(items) / 100)
    return 100 * (bins - lb) / lb
def _w(x): return sim(*x)
