    global POOL
    if POOL is None: POOL = Pool(10)
    return float(np.mean(POOL.map(_w, [(params, s) for s in seeds])))
if __name__ == "__main__":
    p = json.loads(sys.argv[1])
    print("dev", score(p, range(5)), "train", score(p, range(100, 140)))
